const JSON_HEADERS = { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' };
const READ_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

interface HttpErrorOptions {
  status: number;
  code: string;
  details?: unknown;
}

