    id: `${child.id}:${resource.resourceId}`,
    moduleId: child.id,
    sourceModuleId: child.id,
    foldedIntoModuleId: manifest.id,
    href: `${childManifest.owner?.mountPath ?? `${navigation?.path ?? `/modules/${manifest.id}`}/${child.id}`}/${resource.resourceId}`,
