const ID_PATTERN = /^[a-z][a-z0-9-]*(?:\.[a-z0-9-]+)*$/;
const MODULE_PATTERN = /^[a-z][a-z0-9-]*$/;
const COMPILED_PATTERNS = new WeakMap<AdminJsonSchema, RegExp>();
