  ) {
    issues.push({
      path,
      message: "must match at least one allowed schema",
      keyword: "anyOf",
    });
  }
  if (
    schema.oneOf &&
    schema.oneOf.filter(
      (candidate) => validateAdminValue(candidate, value, path).length === 0,
