643	  private relativePath(pathname: string): string {
644	    const prefix = this.registry.apiBasePath;
645	    if (pathname !== prefix && !pathname.startsWith(`${prefix}/`)) throw new SuperConsoleHttpError('The request is outside the administration API.', { status: 404, code: 'ADMIN_ROUTE_NOT_FOUND' });
646	    const suffix = pathname.slice(prefix.length);
647	    if (suffix.includes('\\') || suffix.includes('//')) {
648	      throw new SuperConsoleHttpError('The administration path is not canonical.', { status: 400, code: 'INVALID_ADMIN_PATH' });
649	    }
650	    const rawSegments = suffix.replace(/^\/+|\/+$/g, '').split('/').filter(Boolean);
651	    const decodedSegments = rawSegments.map((segment) => {
652	      let decoded = segment;
653	      for (let depth = 0; depth < 4; depth += 1) {
654	        let next: string;
655	        try {
656	          next = decodeURIComponent(decoded);
657	        } catch {
658	          throw new SuperConsoleHttpError('The administration path contains invalid percent encoding.', { status: 400, code: 'INVALID_ADMIN_PATH' });
659	        }
660	        if (next === '.' || next === '..' || /[\/\\\u0000-\u001f\u007f]/.test(next)) {
661	          throw new SuperConsoleHttpError('The administration path contains an unsafe segment.', { status: 400, code: 'INVALID_ADMIN_PATH' });
662	        }
663	        if (next === decoded) return segment;
664	        decoded = next;
665	      }
666	      if (/%[0-9a-f]{2}/i.test(decoded)) {
667	        throw new SuperConsoleHttpError('The administration path contains unstable nested encoding.', { status: 400, code: 'INVALID_ADMIN_PATH' });
668	      }
669	      return segment;
670	    });
671	    return decodedSegments.join('/');
672	  }
