140	 * Function-owned Super Console integration. It preserves provider plugins,
141	 * hooks, rate limits, two-factor semantics, CSRF, and cookie behavior while
142	 * satisfying the console's provider-neutral operator-auth contract.
143	 */
144	export function createAuthFnOperatorAuth<
145	  TPrincipal extends AuthFnOperatorPrincipal,
146	  TPlugins extends AuthFnPluginList,
147	>(
148	  options: AuthFnOperatorAuthOptions<TPrincipal, TPlugins>,
149	) {
150	  const authFn = authfn(options.config).createServer(options.config);
151	  const basePath = (options.config.basePath ?? '/auth').replace(/\/+$/, '') || '/';
152	  const route = (suffix: string) => `${basePath === '/' ? '' : basePath}${suffix}`;
153	
154	  return {
155	    async authenticate(request: Request) {
156	      const session = await authFn.provider.authenticate(request);
157	      if (!session) return null;
158	      const principal = await options.resolveOperator({ session, request });
159	      return principal ? withCookieNames(authFn, principal, request) : null;
160	    },
161	    async authorizeScope(input: { principal: TPrincipal; requested: AdminScope; request: Request }) {
162	      return options.authorizeScope(input);
163	    },
164	    async authorizeMutation({ request }: { principal: TPrincipal; request: Request }) {
165	      await authFn.authorizeMutation(request);
166	    },
167	    async signIn({ email, password, request }: { email: string; password: string; request: Request }) {
168	      const upstream = await authFn.router.handle(authRequest(request, route('/sign-in/password'), {
169	        email,
170	        password,
171	        sessionMode: 'cookie',
172	      }));
173	      return resolveSuccessfulOperator(authFn, options, upstream, await envelope(upstream), request);
174	    },
175	    async completeTwoFactor({ challengeId, code, request }: { challengeId: string; code: string; request: Request }) {
176	      const upstream = await authFn.router.handle(authRequest(request, route('/2fa/challenge'), { challengeId, code }));
177	      return resolveSuccessfulOperator(authFn, options, upstream, await envelope(upstream), request);
178	    },
179	    async signOut({ request }: { principal: TPrincipal | null; request: Request }) {
180	      const upstream = await authFn.router.handle(authRequest(request, route('/sign-out'), {}));
181	      const payload = await envelope(upstream);
182	      if (!upstream.ok || payload.ok === false) throwAuthResponse(upstream, payload);
183	      return { headers: authResponseHeaders(upstream) };
184	    },
185	    mapError(error: unknown): Response | undefined {
186	      if (error instanceof AuthFnOperatorResponseError) {
187	        if (error.payload.error?.code !== 'AUTHFN_2FA_REQUIRED') return error.response;
188	        return new Response(JSON.stringify({
189	          ...error.payload,
190	          error: { ...error.payload.error, code: 'OPERATOR_2FA_REQUIRED' },
191	        }), { status: error.response.status, headers: authResponseHeaders(error.response) });
192	      }
193	      if (error instanceof AuthFnError) {
194	        return new Response(JSON.stringify({
195	          ok: false,
196	          error: {
197	            code: error.code,
198	            message: error.message,
199	            status: error.status,
