    expect(safeAdminDownloadHref('javascript:alert(1)')).toBeUndefined();
    expect(safeAdminDownloadHref('/api/admin/v1/modules/cifn/artifacts/1')).toBe('/api/admin/v1/modules/cifn/artifacts/1');

