      .find((value) => value !== null && value !== undefined);
    return { key, label: adminFieldLabel(key), format: adminFieldFormat(key, sample) };
  });
}

function adminItemId(
  item: Record<string, unknown>,
  resourceId: string,
  idField?: string
): string | undefined {
  const singular = resourceId.endsWith('ies')
