  'workspaceId',
  'projectId',
  'environmentId',
  'namespace',
  'region',
] as const;

const ADMIN_SCOPE_HIERARCHY = [
  {
    key: 'installationId',
    aliases: ['installationId', 'installation', 'organizationId', 'organization'],
  },
  { key: 'workspaceId', aliases: ['workspaceId', 'workspace'] },
